import{_ as i,l as s,o as e,c as n,v as t,p as l,x as r,d as h,i as d,S as T}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"BitTorrent 与 DHT","description":"","frontmatter":{"title":"BitTorrent 与 DHT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bittorrent-dht.md","filePath":"cs/bittorrent-dht.md","lastUpdated":1789023840000}'),p={name:"cs/bittorrent-dht.md"};function c(D,a,m,_,E,P){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="bittorrent-与-dht" tabindex="-1">BitTorrent 与 DHT <a class="header-anchor" href="#bittorrent-与-dht" aria-label="Permalink to &quot;BitTorrent 与 DHT&quot;">​</a></h1><div class="epigraph"><p>文件切成块，对等方互传；tracker 或 DHT 负责发现邻居。稀有块优先，使复制在群体里展开，而不是一台源打满 $C$。</p><footer>—— 据 Cohen, The BitTorrent Protocol；RFC 9529 等 DHT 实践；Kademlia 对照整理</footer></div><p><a href="/cs/ftp-passive">FTP</a> 是中心源。<a href="/cs/ftp-passive">上一课</a> 结束该课序。缺口是 <strong>P2P 分发</strong>：swarm、片、DHT。本课不把 WebRTC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>热门文件把 HTTP 源与 CDN 账单打满。BitTorrent：元数据列块哈希，对等互传，稀缺优先，tit-for-tat 激励上传。Tracker 集中列表；DHT（Kademlia 风格）用 infohash 找 peers，无单点。NAT 仍痛，要打洞或中继。不是多播树，是应用层覆盖。</p><p>不要把 DHT 写成 DNS。</p><p><span class="marginnote">Cohen 规范。BEP 文档。本课不写盗版场景。</span></p><h3 id="应用层-mesh" tabindex="-1">应用层 mesh <a class="header-anchor" href="#应用层-mesh" aria-label="Permalink to &quot;应用层 mesh&quot;">​</a></h3><p>块哈希防污染；DHT 去中心发现。不是 DNS，也不是 IP 多播树。NAT 与激励是部署约束。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：种子 → 块 → 邻居集合。对照 CDN：CDN 有树与缓存层次，BT 有 mesh。与 ECMP 无关直接。</p>',11)),(e(),l(T,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22infohash%20%E4%B8%8E%E5%9D%97%22%5D%20--%3E%20DISC%5B%22tracker%20%E6%88%96%20DHT%22%5D%0A%20%20DISC%20--%3E%20PEER%5B%22%E5%AF%B9%E7%AD%89%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20PEER%20--%3E%20RARE%5B%22%E7%A8%80%E6%9C%89%E5%9D%97%E4%BC%98%E5%85%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传输仍是 TCP（或 μTP），拥塞各连接 AIMD，共享接入会互抢——接入 AQM 有帮助。DNS 可找 tracker。加密扩展点名。GeoDNS 不调度块。</p><p>安全：污染块靠哈希；DHT 污染是另一攻击面，点名不展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BitTorrent v2 的全部。WebRTC 与 ICE 是下一课。后课默认：P2P 分发 = 块交换 + 发现；DHT 去中心发现。</p><p>企业网禁 P2P 端口是政策，不是协议缺陷。</p><p>上一课留下的缺口在本课收口；「BitTorrent 与 DHT」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/webrtc-ice">WebRTC 与 ICE</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>块交换摊源；稀有优先。</li><li>Tracker 或 DHT 发现邻居。</li><li>覆盖网在应用层，NAT 是障碍。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Cohen；Kademlia/DHT 实践。</li></ul>',10))])}const C=i(p,[["render",c]]);export{b as __pageData,C as default};
